const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createTutor(getContext){let opened=false,busy=false,error='',draft='',configured=null,context=null,history=[],controller=null,returnFocus=null,generation=0;const root=document.createElement('div');root.id='tutor-root';document.body.append(root);
 const labels={primary:['Ask Pip’s learning helper','Let’s discover it together.'],middle:['Discovery guide','Predict, explore, and ask why.'],secondary:['Learning assistant','Work through the problem. Understand each step.'],advanced:['Research tutor','Examine assumptions. Develop your reasoning.']};
 function draw(){if(!opened){root.innerHTML='';return}const label=labels[context.age];root.innerHTML=`<div class="tutor-overlay"><section class="tutor-panel tutor-${context.age}" role="dialog" aria-modal="true" aria-labelledby="tutor-title"><header class="tutor-header"><div><span class="eyebrow">NEXORA AI LEARNING ASSISTANT</span><h2 id="tutor-title">${label[0]}</h2><p>${label[1]}</p></div><button class="btn secondary small" data-tutor="close" aria-label="Return to lesson">✕</button></header><div class="tutor-context"><span class="pill blue">${escape(context.label)}</span><button class="link" data-tutor="clear">New conversation</button></div><p class="tutor-notice">${configured===false?'AI is not configured here. Run the included server and set OPENAI_API_KEY to enable it. Lessons still work.':configured===null?'Checking tutor availability…':'AI responses can be mistaken. Check important results. Questions and lesson context are sent to OpenAI; avoid personal information.'}</p><div class="tutor-messages" aria-live="polite" aria-relevant="additions text">${history.length?history.map((m,i)=>`<article class="tutor-message ${m.role}"><b>${m.role==='user'?'You':'NEXORA tutor'}</b><div class="tutor-response">${escape(m.content)}</div>${m.role==='assistant'?`<div class="audio"><button data-read="${i}">Read aloud</button><button data-copy="${i}">Copy</button><button data-tutor="stop">Stop audio</button></div>`:''}</article>`).join(''):`<div class="tutor-empty"><span>✦</span><h3>Bring your curiosity.</h3><p>Ask a question, request a hint, or explore a new example.</p></div>`}${busy?'<p role="status">Thinking through your question…</p>':''}${error?`<div class="feedback" role="alert">${escape(error)} <button class="link" data-tutor="retry">Retry</button></div>`:''}</div><div class="tutor-suggestions">${['Explain this with a different example.','Give me one hint, then let me try.','Make a practice question for my level.','Summarize the key ideas.'].map(s=>`<button data-suggest="${escape(s)}">${s}</button>`).join('')}</div><form id="tutor-form"><label for="tutor-question">Your question</label><div class="tutor-input-row"><textarea id="tutor-question" maxlength="4000" rows="2" placeholder="What would you like to understand?" ${busy?'disabled':''}>${escape(draft)}</textarea><button class="btn" ${busy?'disabled':''}>Send →</button></div><p class="micro">Conversation stays in this tab only. Opening a different age or lesson starts fresh.</p></form></section></div>`;root.querySelector('.tutor-messages').scrollTop=1e9;root.querySelector(busy?'[data-tutor=close]':'#tutor-question')?.focus();}
 async function send(retry=false){if(busy)return;const question=draft.trim();if(!retry){if(!question)return;history.push({role:'user',content:question});draft=''}else if(history.at(-1)?.role!=='user')return;const requestGeneration=generation;busy=true;error='';controller=new AbortController();draw();const timeout=setTimeout(()=>controller?.abort(),30000);try{let messages=history.slice(-12);while(messages.reduce((n,m)=>n+m.content.length,0)>15000&&messages.length>1)messages.shift();const r=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...context,messages}),signal:controller.signal});let data;try{data=await r.json()}catch{throw Error('The AI server is not available on this deployment. Run npm start from the ZIP to use the server integration.')}if(!r.ok)throw Error(data.error||'The tutor is unavailable. Please retry.');if(typeof data.answer!=='string'||!data.answer.trim())throw Error('The tutor returned an empty response.');if(requestGeneration===generation){history.push({role:'assistant',content:data.answer});configured=true}}catch(e){if(requestGeneration!==generation)return;error=e.name==='AbortError'?'The request was stopped or timed out. You can retry.':e.message}finally{clearTimeout(timeout);if(requestGeneration===generation){busy=false;controller=null;if(opened)draw()}}}
 async function open(){returnFocus=document.activeElement;const next=getContext();if(!context||JSON.stringify({...context,mastery:0})!==JSON.stringify({...next,mastery:0})){controller?.abort();generation++;busy=false;history=[];error='';draft=''}context=next;opened=true;draw();document.querySelector('#app').inert=true;root.querySelector('#tutor-question')?.focus();try{const r=await fetch('/api/assistant/status');const data=await r.json();configured=r.ok&&data.configured===true}catch{configured=false}if(opened)draw()}
 function close(){opened=false;document.querySelector('#app').inert=false;window.speechSynthesis?.cancel();draw();returnFocus?.focus()}
 root.addEventListener('input',e=>{if(e.target.id==='tutor-question')draft=e.target.value});root.addEventListener('submit',e=>{if(e.target.id==='tutor-form'){e.preventDefault();send()}});
 root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.tutor;if(a==='close')close();if(a==='clear'){controller?.abort();if(busy){error='Please wait for the current request to stop.';draw();return}history=[];draft='';error='';draw()}if(a==='retry')send(true);if(a==='stop')window.speechSynthesis?.cancel();if(b.dataset.suggest){draft=b.dataset.suggest;draw();root.querySelector('#tutor-question').focus()}if(b.dataset.read){if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(history[Number(b.dataset.read)].content))}else{error='Read aloud is unavailable in this browser.';draw()}}if(b.dataset.copy){try{await navigator.clipboard.writeText(history[Number(b.dataset.copy)].content);b.textContent='Copied'}catch{error='Copy is unavailable. Select the response text to copy it.';draw()}}});
 document.addEventListener('keydown',e=>{if(!opened)return;if(e.key==='Escape')close();if(e.key==='Tab'){const focusable=[...root.querySelectorAll('button:not([disabled]),textarea:not([disabled])')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});return {open,reset(){controller?.abort();generation++;busy=false;history=[];draft='';error='';context=null;close()}};}
